suppressPackageStartupMessages({library(data.table);library(hgu133plus2.db);library(AnnotationDbi)})
root<-".";f<-file.path(root,"data_raw","GSE18105_series_matrix.txt.gz");out<-file.path(root,"results_tables");logd<-file.path(root,"logs")
con<-gzfile(f,"rt");raw<-readLines(con,warn=FALSE);close(con);begin<-which(grepl("!series_matrix_table_begin",raw,fixed=TRUE));end<-which(grepl("!series_matrix_table_end",raw,fixed=TRUE));tab<-fread(text=paste(raw[(begin+1):(end-1)],collapse="\n"),sep="\t",header=TRUE,check.names=FALSE,quote="\"",data.table=TRUE)
sample_line<-raw[grepl("!Sample_geo_accession",raw,fixed=TRUE)][1];ids<-gsub('^"|"$','',strsplit(sub("^!Sample_geo_accession\\t","",sample_line),"\\t")[[1]]);X<-as.matrix(tab[,-1,with=FALSE]);storage.mode(X)<-"numeric";colnames(X)<-ids;probe<-as.character(tab[[1]])
map<-as.data.table(AnnotationDbi::select(hgu133plus2.db,keys=probe,keytype="PROBEID",columns=c("SYMBOL","ENTREZID")));map<-map[SYMBOL%in%c("FASN","SCD")&!is.na(SYMBOL)];expr<-data.table(sample_id=ids,FASN=NA_real_,SCD=NA_real_);for(g in c("FASN","SCD")){ii<-match(map[SYMBOL==g,PROBEID],probe);expr[[g]]<-colMeans(X[ii,,drop=FALSE],na.rm=TRUE)}
chars<-raw[grepl("!Sample_characteristics_ch1",raw,fixed=TRUE)];cm<-lapply(chars,function(z){q<-strsplit(sub("^!Sample_characteristics_ch1\\t","",z),"\\t")[[1]];gsub('^"|"$','',q)});ch<-as.data.table(do.call(rbind,cm));ch<-transpose(ch);ch[,sample_id:=ids]
getfield<-function(v,key){z<-as.character(v);ii<-startsWith(tolower(z),tolower(paste0(key,":")));out<-rep(NA_character_,length(z));out[ii]<-sub("^[^:]*:\\s*","",z[ii]);out}
expr[,metastasis:=getfield(ch[[1]],"metastasis")];expr[,tissue:=getfield(ch[[2]],"tissue")];expr<-expr[tissue=="cancer, LCM"];expr[,FASN:=as.numeric(FASN)];expr[,SCD:=as.numeric(SCD)];fwrite(expr,file.path(out,"GSE18105_FASN_SCD_metastasis_matrix.tsv"),sep="\t",na="NA")
test<-function(v){z<-expr[metastasis%in%c("none","metastasis","metastatic recurrence")&is.finite(get(v))];z[,g:=factor(metastasis,levels=c("none","metastasis","metastatic recurrence"))];z[,metastasis_any:=g!="none"];kw<-kruskal.test(get(v)~g,data=z);pair<-wilcox.test(get(v)~metastasis_any,data=z,exact=FALSE);data.table(dataset="GSE18105",feature=v,n=nrow(z),none_n=sum(z$g=="none"),metastasis_n=sum(z$g=="metastasis"),metastatic_recurrence_n=sum(z$g=="metastatic recurrence"),kruskal_p=kw$p.value,metastasis_any_p=pair$p.value)}
r<-rbind(test("FASN"),test("SCD"));r[,p_adj:=p.adjust(kruskal_p,"BH")];fwrite(r,file.path(out,"GSE18105_metastasis_association_results.tsv"),sep="\t",na="NA")
qc<-data.table(accession="GSE18105",matrix_samples=ncol(X),matrix_probes=nrow(tab),cancer_lcm_samples=nrow(expr),FASN_detected=sum(is.finite(expr$FASN)),SCD_detected=sum(is.finite(expr$SCD),na.rm=TRUE),stage_available=FALSE,OS_available=FALSE,note="Official sample characteristics provide metastasis status and tissue type; no sample-level stage/OS fields")
fwrite(qc,file.path(out,"GSE18105_validation_qc.tsv"),sep="\t",na="NA");capture.output(sessionInfo(),file=file.path(logd,"gse18105_validation_sessionInfo.txt"));cat("GSE18105 metastasis validation completed; cancer LCM samples",nrow(expr),"\n")
